<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$errors=[];$id=max(0,scalar_int($_GET['edit']??$_POST['id']??0));
if(is_post()){
    verify_csrf();
    try{$name=trim(scalar_string($_POST['name']??''));$code=slugify(scalar_string($_POST['code']??$name));$phone=trim(scalar_string($_POST['phone']??''));$template=trim(scalar_string($_POST['tracking_url_template']??''));$active=isset($_POST['is_active'])?1:0;$sort=max(-10000,min(10000,scalar_int($_POST['sort_order']??0)));if(text_length($name)<2||text_length($name)>160||!preg_match('/^[a-z0-9-]{2,80}$/',$code))throw new RuntimeException('نام یا کد شرکت حمل معتبر نیست.');if(text_length($phone)>30||text_length($template)>500)throw new RuntimeException('تلفن یا نشانی رهگیری بیش از حد طولانی است.');if($template!==''&&(!str_contains($template,'{code}')||!filter_var(str_replace('{code}','TEST',$template),FILTER_VALIDATE_URL)))throw new RuntimeException('الگوی رهگیری باید آدرس کامل و شامل {code} باشد.');if($id>0)db()->prepare('UPDATE shipping_carriers SET name=?,code=?,phone=?,tracking_url_template=?,is_active=?,sort_order=? WHERE id=?')->execute([$name,$code,$phone?:null,$template?:null,$active,$sort,$id]);else{db()->prepare('INSERT INTO shipping_carriers(name,code,phone,tracking_url_template,is_active,sort_order) VALUES(?,?,?,?,?,?)')->execute([$name,$code,$phone?:null,$template?:null,$active,$sort]);$id=(int)db()->lastInsertId();}admin_audit_event('carrier_saved','carrier',$id);flash('success','شرکت حمل ذخیره شد.');redirect(app_url('admin/shipping.php?edit='.$id));}catch(Throwable $e){$errors[]=$e instanceof PDOException?'کد شرکت حمل تکراری است.':$e->getMessage();}
}
$edit=null;if($id>0){$stmt=db()->prepare('SELECT * FROM shipping_carriers WHERE id=?');$stmt->execute([$id]);$edit=$stmt->fetch()?:null;}$carriers=db()->query('SELECT c.*,(SELECT COUNT(*) FROM shipments s WHERE s.carrier_id=c.id) shipment_count FROM shipping_carriers c ORDER BY sort_order,name')->fetchAll();$adminPage='shipments';$adminTitle='شرکت‌های حمل';require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>شرکت‌های حمل و رهگیری</h1><p class="muted">برای ساخت لینک رهگیری، در آدرس شرکت حمل از متغیر {code} استفاده کنید.</p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/shipments.php'))?>">پرونده‌های ارسال</a></div><?php foreach($errors as $error):?><div class="flash error"><?=e($error)?></div><?php endforeach?><form method="post" class="card"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>نام شرکت حمل</label><input name="name" maxlength="160" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label>کد انگلیسی</label><input name="code" dir="ltr" maxlength="80" value="<?=e($edit['code']??'')?>" required></div><div class="field"><label>تلفن</label><input name="phone" maxlength="30" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label>ترتیب</label><input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></div><div class="field full"><label>الگوی لینک رهگیری</label><input name="tracking_url_template" dir="ltr" maxlength="500" value="<?=e($edit['tracking_url_template']??'')?>" placeholder="https://carrier.example/track/{code}"></div><div class="field"><label><input type="checkbox" name="is_active" value="1" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> فعال</label></div></div><button class="btn btn-primary">ذخیره</button><?php if($edit):?><a class="btn btn-secondary" href="<?=e(app_url('admin/shipping.php'))?>">جدید</a><?php endif?></form><div class="table-wrap"><table><thead><tr><th>نام</th><th>کد</th><th>تلفن</th><th>ارسال‌ها</th><th>رهگیری</th><th>عملیات</th></tr></thead><tbody><?php foreach($carriers as $carrier):?><tr><td><strong><?=e($carrier['name'])?></strong><br><small><?=$carrier['is_active']?'فعال':'غیرفعال'?></small></td><td dir="ltr"><?=e($carrier['code'])?></td><td><?=e($carrier['phone']?:'—')?></td><td><?=fa_number($carrier['shipment_count'])?></td><td><?=e($carrier['tracking_url_template']?'فعال':'بدون لینک')?></td><td><a class="btn btn-secondary btn-sm" href="<?=e(app_url('admin/shipping.php?edit='.(int)$carrier['id']))?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div>
